// ═══════════════════════════════════════════════════════════════════════
// 4. GEOMETRY FACTORIES
// ═══════════════════════════════════════════════════════════════════════

/**
 * Creates a tube geometry with varying radius along its length.
 * This is the key function for realistic muscle bellies and tapered bones.
 */
function variableRadiusTube(
  path: THREE.Vector3[],
  tubularSegments: number,
  radiusFn: (t: number) => number,
  radialSegments: number = 8,
): THREE.BufferGeometry {
  if (path.length < 2) return new THREE.SphereGeometry(radiusFn(0.5), 8, 6);

  const curve = new THREE.CatmullRomCurve3(path, false, "catmullrom", 0.5);
  const frames = curve.computeFrenetFrames(tubularSegments, false);

  const vertices: number[] = [];
  const normals: number[] = [];
  const uvs: number[] = [];
  const indices: number[] = [];

  for (let i = 0; i <= tubularSegments; i++) {
    const t = i / tubularSegments;
    const P = curve.getPointAt(t);
    const N = frames.normals[i]!;
    const B = frames.binormals[i]!;
    const r = radiusFn(t);

    for (let j = 0; j <= radialSegments; j++) {
      const v = (j / radialSegments) * Math.PI * 2;
      const sin = Math.sin(v);
      const cos = -Math.cos(v);

      const nx = cos * N.x + sin * B.x;
      const ny = cos * N.y + sin * B.y;
      const nz = cos * N.z + sin * B.z;
      const len = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;

      vertices.push(P.x + r * nx, P.y + r * ny, P.z + r * nz);
      normals.push(nx / len, ny / len, nz / len);
      uvs.push(j / radialSegments, t);
    }
  }

  for (let i = 0; i < tubularSegments; i++) {
    for (let j = 0; j < radialSegments; j++) {
      const a = i * (radialSegments + 1) + j;
      const b = (i + 1) * (radialSegments + 1) + j;
      const c = (i + 1) * (radialSegments + 1) + (j + 1);
      const d = i * (radialSegments + 1) + (j + 1);
      indices.push(a, b, d, b, c, d);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setIndex(indices);
  geo.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geo.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  return geo;
}

function tubeFromPath(points: THREE.Vector3[], radius: number, segments?: number): THREE.BufferGeometry {
  if (points.length < 2) return new THREE.SphereGeometry(radius, 6, 4);
  const curve = new THREE.CatmullRomCurve3(points, false, "catmullrom", 0.5);
  const tubeSeg = segments ?? Math.max(4, Math.min(32, Math.ceil(curve.getLength() / 2)));
  return new THREE.TubeGeometry(curve, tubeSeg, radius, 6, false);
}

function longBoneGeometry(length: number, width: number, depth: number): THREE.BufferGeometry {
  const r = (width + depth) / 4;
  const epiphR = r * 1.35;
  const diaphR = r * 0.7;
  const h = Math.max(0.5, length);

  const nPts = 7;
  const pts: THREE.Vector3[] = [];
  for (let i = 0; i < nPts; i++) {
    pts.push(new THREE.Vector3(0, -h / 2 + (h * i) / (nPts - 1), 0));
  }

  return variableRadiusTube(pts, 16, (t) => {
    const endProx = Math.exp(-((t * 5) ** 2));
    const endDist = Math.exp(-(((1 - t) * 5) ** 2));
    const endInfluence = Math.max(endProx, endDist);
    return diaphR + (epiphR - diaphR) * endInfluence;
  }, 10);
}

function boneGeometry(bone: BoneData): THREE.BufferGeometry {
  const cls = bone.classification;
  const l = bone.length;
  const w = bone.width;
  const d = bone.depth;

  switch (cls) {
    case "long": {
      return longBoneGeometry(l, w, d);
    }
    case "flat": {
      // Flattened box — cranial/rib bones, with slight curvature
      const geo = new THREE.BoxGeometry(w, l * 0.15, d, 4, 1, 4);
      // Bend flat bones slightly for anatomical curvature
      const pos = geo.attributes.position as THREE.BufferAttribute;
      for (let i = 0; i < pos.count; i++) {
        const x = pos.getX(i);
        const z = pos.getZ(i);
        const dist = Math.sqrt(x * x + z * z);
        pos.setY(i, pos.getY(i) + dist * 0.05);
      }
      geo.computeVertexNormals();
      return geo;
    }
    case "irregular": {
      // Organic-looking shape: smooth icosahedron with subtle perturbation
      const ico = new THREE.IcosahedronGeometry(1, 2);
      const pos = ico.attributes.position as THREE.BufferAttribute;
      for (let i = 0; i < pos.count; i++) {
        const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
        const len = Math.sqrt(x * x + y * y + z * z) || 1;
        const nx = x / len, ny = y / len, nz = z / len;
        // Subtle organic noise — just enough to break perfect symmetry
        const noise = 1.0
          + 0.04 * Math.sin(nx * 5.3 + ny * 3.1)
          + 0.03 * Math.cos(nz * 4.7 + nx * 2.2);
        pos.setXYZ(i, nx * (w / 2) * noise, ny * (l / 2) * noise, nz * (d / 2) * noise);
      }
      ico.computeVertexNormals();
      return ico;
    }
    case "short": {
      // Rounded cube — carpals, tarsals
      const geo = new THREE.IcosahedronGeometry(1, 1);
      geo.scale(w / 2, l / 2, d / 2);
      return geo;
    }
    case "sesamoid": {
      // Smooth sphere — patella, sesamoids
      const r = Math.max(w, d, l) / 2;
      return new THREE.SphereGeometry(r, 12, 10);
    }
    default:
      return new THREE.SphereGeometry(l / 2, 8, 6);
  }
}

/**
 * Organ-specific geometry based on organ name/system.
 * Each organ type gets a distinct silhouette instead of a generic ellipsoid.
 */
function organGeometry(organ: OrganData): THREE.BufferGeometry {
  const name = organ.name.toLowerCase();
  const vol = organ.volume;
  const k = Math.cbrt(vol / ((4 / 3) * Math.PI));

  if (name.includes("heart")) {
    return heartGeometry(k);
  }
  if (name.includes("lung")) {
    return lungGeometry(k, name.includes("(l)") || name.includes("left") ? -1 : 1);
  }
  if (name.includes("brain") || name.includes("cerebr")) {
    return brainGeometry(k);
  }
  if (name.includes("kidney")) {
    return kidneyGeometry(k);
  }
  if (name.includes("liver")) {
    return liverGeometry(k);
  }
  if (name.includes("stomach")) {
    return stomachGeometry(k);
  }
  if (name.includes("intestin")) {
    return intestineGeometry(k, name.includes("large") || name.includes("colon"));
  }
  if (name.includes("bladder")) {
    return bladderGeometry(k);
  }

  // Default: organic ellipsoid with perturbation
  return defaultOrganGeometry(vol);
}

function heartGeometry(k: number): THREE.BufferGeometry {
  // Heart-like shape: rounded top with tapered bottom (apex)
  const pts: THREE.Vector2[] = [];
  for (let i = 0; i <= 20; i++) {
    const t = i / 20;
    const angle = t * Math.PI;
    // Heart profile: wide at top 1/3, tapering to apex at bottom
    let r: number;
    if (t < 0.15) {
      // Flat top (base of heart, where vessels attach)
      r = 0.6 + t * 1.5;
    } else if (t < 0.55) {
      // Wide rounded body
      r = Math.sin(angle) * 1.1;
    } else {
      // Taper to apex
      const taper = (1 - t) / 0.45;
      r = Math.sin(angle) * 0.9 * taper;
    }
    pts.push(new THREE.Vector2(Math.max(0.01, r * k * 1.0), (t - 0.5) * k * 2.8));
  }
  const geo = new THREE.LatheGeometry(pts, 16);
  geo.computeVertexNormals();
  return geo;
}

function lungGeometry(k: number, side: number): THREE.BufferGeometry {
  // Elongated ellipsoid with medial flat surface and rounded lateral
  const geo = new THREE.SphereGeometry(1, 16, 12);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    // Flatten medial side (towards center of body)
    if (x * side < 0) {
      x *= 0.6;
    }
    // Taper top (apex)
    const yNorm = (y + 1) / 2; // 0=bottom, 1=top
    const taperTop = yNorm > 0.7 ? 1 - (yNorm - 0.7) / 0.3 * 0.4 : 1;
    // Widen bottom
    const widenBot = yNorm < 0.3 ? 1 + (0.3 - yNorm) / 0.3 * 0.15 : 1;
    pos.setXYZ(i,
      x * k * 1.2 * taperTop * widenBot,
      y * k * 1.8,
      z * k * 1.0 * taperTop * widenBot,
    );
  }
  geo.computeVertexNormals();
  return geo;
}

function brainGeometry(k: number): THREE.BufferGeometry {
  // Sphere with sulci/gyri wrinkles via vertex displacement
  const geo = new THREE.IcosahedronGeometry(k * 1.3, 4);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const len = Math.sqrt(x * x + y * y + z * z) || 1;
    const nx = x / len, ny = y / len, nz = z / len;
    // Multi-frequency noise for wrinkled surface
    const wrinkle =
      0.06 * Math.sin(nx * 18 + nz * 12) * Math.cos(ny * 15 + nx * 8) +
      0.04 * Math.sin(ny * 22 + nz * 16) * Math.cos(nx * 20) +
      0.03 * Math.cos(nz * 28 + nx * 14 + ny * 10);
    const r = len * (1 + wrinkle);
    // Slightly flatten top, elongate front-back
    pos.setXYZ(i, nx * r * 1.05, ny * r * 0.85, nz * r * 1.15);
  }
  geo.computeVertexNormals();
  return geo;
}

function kidneyGeometry(k: number): THREE.BufferGeometry {
  // Bean shape using a torus section
  const geo = new THREE.TorusGeometry(k * 0.8, k * 0.5, 12, 16, Math.PI * 1.3);
  geo.rotateX(Math.PI / 2);
  geo.rotateZ(Math.PI * 0.15);
  geo.computeVertexNormals();
  return geo;
}

function liverGeometry(k: number): THREE.BufferGeometry {
  // Wide, flat, wedge-shaped organ
  const geo = new THREE.SphereGeometry(1, 14, 10);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  for (let i = 0; i < pos.count; i++) {
    let x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    // Flatten vertically, widen horizontally
    // Right lobe larger than left
    const xBias = x > 0 ? 1.3 : 0.8;
    pos.setXYZ(i, x * k * 2.0 * xBias, y * k * 0.6, z * k * 1.4);
  }
  geo.computeVertexNormals();
  return geo;
}

function stomachGeometry(k: number): THREE.BufferGeometry {
  // J-shaped curved tube with variable radius
  const pts: THREE.Vector3[] = [];
  for (let i = 0; i <= 12; i++) {
    const t = i / 12;
    const angle = t * Math.PI * 0.8;
    pts.push(new THREE.Vector3(
      Math.sin(angle) * k * 1.5,
      -t * k * 2.5,
      Math.cos(angle) * k * 0.3,
    ));
  }
  return variableRadiusTube(pts, 16, (t) => {
    // Wide at fundus (top), narrow at pylorus (bottom)
    const fundus = Math.exp(-((t * 3) ** 2)) * 0.4;
    const body = Math.sin(t * Math.PI) * 0.6;
    return k * (0.3 + fundus + body);
  }, 10);
}

function intestineGeometry(k: number, isLarge: boolean): THREE.BufferGeometry {
  // Coiled tube
  const r = isLarge ? k * 0.5 : k * 0.2;
  const coilR = isLarge ? k * 2.0 : k * 1.5;
  const turns = isLarge ? 1.5 : 4;
  const pts: THREE.Vector3[] = [];
  const nPts = Math.ceil(turns * 12);
  for (let i = 0; i <= nPts; i++) {
    const t = i / nPts;
    const angle = t * turns * Math.PI * 2;
    pts.push(new THREE.Vector3(
      Math.cos(angle) * coilR * (0.5 + t * 0.5),
      -t * k * 3,
      Math.sin(angle) * coilR * (0.5 + t * 0.5),
    ));
  }
  return variableRadiusTube(pts, Math.max(12, nPts * 2), () => r, 8);
}

function bladderGeometry(k: number): THREE.BufferGeometry {
  // Pear-shaped: wider at top, narrow at base
  const pts: THREE.Vector2[] = [];
  for (let i = 0; i <= 16; i++) {
    const t = i / 16;
    const r = Math.sin(t * Math.PI) * (1 - t * 0.3);
    pts.push(new THREE.Vector2(Math.max(0.01, r * k * 1.0), (t - 0.5) * k * 1.6));
  }
  return new THREE.LatheGeometry(pts, 12);
}

function defaultOrganGeometry(vol: number): THREE.BufferGeometry {
  // Organic ellipsoid with slight perturbation
  const k = Math.cbrt(vol / ((4 / 3) * Math.PI * 1.0 * 1.5 * 0.8));
  const a = k * 1.0;
  const b = k * 1.5;
  const c = k * 0.8;

  const geo = new THREE.SphereGeometry(1, 14, 10);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const len = Math.sqrt(x * x + y * y + z * z) || 1;
    const nx = x / len, ny = y / len, nz = z / len;
    // Subtle organic noise
    const noise = 1.0 + 0.05 * Math.sin(nx * 10 + ny * 8) * Math.cos(nz * 12);
    pos.setXYZ(i, nx * a * noise, ny * b * noise, nz * c * noise);
  }
  geo.computeVertexNormals();
  return geo;
}

// ═══════════════════════════════════════════════════════════════════════
// 5. SCENE LAYER GROUPS — toggleable visibility
// ═══════════════════════════════════════════════════════════════════════

export type LayerName =
  | "skeleton"
  | "joints"
  | "muscles"
  | "tendons"
  | "organs"
  | "arteries"
  | "veins"
  | "nerves"
  | "ligaments"
  | "cartilage";

export const ALL_LAYERS: LayerName[] = [
  "skeleton", "joints", "muscles", "tendons",
  "organs", "arteries", "veins", "nerves",
  "ligaments", "cartilage",
];

export const DEFAULT_VISIBLE: Set<LayerName> = new Set(["skeleton", "joints", "muscles"]);

// ═══════════════════════════════════════════════════════════════════════
// 6. SCENE ASSEMBLY — builds Three.js scene from HumanBody JSON
// ═══════════════════════════════════════════════════════════════════════

export type ThemeMode = "dark" | "light";

interface ThemeConfig {
  sceneBg: number;
  fogColor: number;
  fogDensity: number;
  groundColor: number;
  gridA: number;
  gridB: number;
  hemiSky: number;
  hemiGround: number;
  hemiIntensity: number;
  ambientColor: number;
  ambientIntensity: number;
  keyIntensity: number;
  fillIntensity: number;
  rimIntensity: number;
  exposure: number;
  bloomStrength: number;
}

const THEMES: Record<ThemeMode, ThemeConfig> = {
  dark: {
    sceneBg: 0x0c0c14, fogColor: 0x0c0c14, fogDensity: 0.0008,
    groundColor: 0x111118, gridA: 0x222244, gridB: 0x181828,
    hemiSky: 0xb0c8e8, hemiGround: 0x2a1a0a, hemiIntensity: 0.5,
    ambientColor: 0x303848, ambientIntensity: 0.4,
    keyIntensity: 1.2, fillIntensity: 0.5, rimIntensity: 0.35,
    exposure: 1.1, bloomStrength: 0.15,
  },
  light: {
    sceneBg: 0xeef2f7, fogColor: 0xeef2f7, fogDensity: 0.0004,
    groundColor: 0xd8dce4, gridA: 0xbbc0cc, gridB: 0xd0d4dc,
    hemiSky: 0xffffff, hemiGround: 0x8899aa, hemiIntensity: 0.8,
    ambientColor: 0xc0c8d4, ambientIntensity: 0.7,
    keyIntensity: 1.0, fillIntensity: 0.6, rimIntensity: 0.25,
    exposure: 1.3, bloomStrength: 0.05,
  },
};

export interface UITheme {
  bg: string;
  bgOverlay: string;
  border: string;
  text: string;
  textMuted: string;
  textDim: string;
  panelBg: string;
  panelBorder: string;
  btnBg: string;
  btnBorder: string;
  btnText: string;
  btnActiveText: string;
  inactiveText: string;
}

const UI_THEMES: Record<ThemeMode, UITheme> = {
  dark: {
    bg: "#0c0c14", bgOverlay: "rgba(12,12,20,.92)", border: "rgba(100,120,180,.15)",
    text: "#e8e8f0", textMuted: "#556688", textDim: "#334455",
    panelBg: "rgba(12,12,20,.92)", panelBorder: "rgba(100,120,180,.15)",
    btnBg: "rgba(60,80,120,.12)", btnBorder: "rgba(80,100,140,.2)",
    btnText: "#8899bb", btnActiveText: "#c8ccd4", inactiveText: "#556677",
  },
  light: {
    bg: "#eef2f7", bgOverlay: "rgba(255,255,255,.94)", border: "rgba(100,120,160,.2)",
    text: "#1a1e2a", textMuted: "#667889", textDim: "#8899aa",
    panelBg: "rgba(255,255,255,.94)", panelBorder: "rgba(100,120,160,.18)",
    btnBg: "rgba(100,120,160,.08)", btnBorder: "rgba(100,120,160,.2)",
    btnText: "#4a5568", btnActiveText: "#1a1e2a", inactiveText: "#8899aa",
  },
};

export interface SceneHandle {
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  renderer: THREE.WebGLRenderer;
  composer: EffectComposer;
  controls: OrbitControls;
  layers: Record<LayerName, THREE.Group>;
  boneMap: Map<string, THREE.Mesh>;
  jointMap: Map<string, THREE.Mesh>;
  themeRefs: {
    hemi: THREE.HemisphereLight;
    ambient: THREE.AmbientLight;
    keyLight: THREE.DirectionalLight;
    fillLight: THREE.DirectionalLight;
    rimLight: THREE.DirectionalLight;
    ground: THREE.Mesh;
    grid: THREE.GridHelper;
    bloom: UnrealBloomPass;
  };
  dispose: () => void;
}

export function applyTheme(handle: SceneHandle, mode: ThemeMode): void {
  const t = THEMES[mode];
  const { scene, renderer, themeRefs } = handle;

  scene.background = new THREE.Color(t.sceneBg);
  (scene.fog as THREE.FogExp2).color.set(t.fogColor);
  (scene.fog as THREE.FogExp2).density = t.fogDensity;

  renderer.toneMappingExposure = t.exposure;

  themeRefs.hemi.color.set(t.hemiSky);
  themeRefs.hemi.groundColor.set(t.hemiGround);
  themeRefs.hemi.intensity = t.hemiIntensity;

  themeRefs.ambient.color.set(t.ambientColor);
  themeRefs.ambient.intensity = t.ambientIntensity;

  themeRefs.keyLight.intensity = t.keyIntensity;
  themeRefs.fillLight.intensity = t.fillIntensity;
  themeRefs.rimLight.intensity = t.rimIntensity;

  ((themeRefs.ground as THREE.Mesh).material as THREE.MeshStandardMaterial).color.set(t.groundColor);

  scene.remove(themeRefs.grid);
  const newGrid = new THREE.GridHelper(200, 40, t.gridA, t.gridB);
  newGrid.position.y = 0.05;
  scene.add(newGrid);
  themeRefs.grid = newGrid;

  themeRefs.bloom.strength = t.bloomStrength;
}

function toV3(v: Vec3): THREE.Vector3 {
  return new THREE.Vector3(v.x, v.y, v.z);
}

/**
 * Generates a procedural studio environment map for realistic PBR reflections.
 * Produces soft top/side lighting that makes wet tissue surfaces look convincing.
 */
function generateEnvironmentMap(renderer: THREE.WebGLRenderer): THREE.Texture {
  const pmremGen = new THREE.PMREMGenerator(renderer);
  pmremGen.compileEquirectangularShader();

  const envScene = new THREE.Scene();
  envScene.background = new THREE.Color(0x202030);

  // Soft studio lighting for the environment map
  const envLight1 = new THREE.DirectionalLight(0xffeedd, 2.5);
  envLight1.position.set(5, 8, 5);
  envScene.add(envLight1);

  const envLight2 = new THREE.DirectionalLight(0xddddff, 1.5);
  envLight2.position.set(-5, 4, -5);
  envScene.add(envLight2);

  const envLight3 = new THREE.DirectionalLight(0xffffff, 1.0);
  envLight3.position.set(0, 10, 0);
  envScene.add(envLight3);

  // Ground bounce
  const envLight4 = new THREE.DirectionalLight(0x444455, 0.5);
  envLight4.position.set(0, -5, 0);
  envScene.add(envLight4);

  const envRT = pmremGen.fromScene(envScene, 0.04);
  const envMap = envRT.texture;
  pmremGen.dispose();

  return envMap;
}

export function buildScene(container: HTMLElement, body: HumanBodyData): SceneHandle {
  const W = container.clientWidth;
  const H = container.clientHeight;

  // ── Renderer ──
  const renderer = new THREE.WebGLRenderer({
    antialias: true,
    powerPreference: "high-performance",
  });
  renderer.setSize(W, H);
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.1;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);

  // ── Scene ──
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0c0c14);
  scene.fog = new THREE.FogExp2(0x0c0c14, 0.0008);

  // ── Environment map for realistic PBR reflections ──
  const envMap = generateEnvironmentMap(renderer);
  scene.environment = envMap;

  // ── Camera — framing full body (Y range 0–180 cm) ──
  const camera = new THREE.PerspectiveCamera(40, W / H, 0.5, 500);
  camera.position.set(60, 100, 120);
  camera.lookAt(0, 90, 0);

  // ── Controls ──
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.target.set(0, 90, 0);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.minDistance = 15;
  controls.maxDistance = 350;
  controls.maxPolarAngle = Math.PI * 0.95;
  controls.update();

  // ── Lighting — 3-point + ambient + hemisphere ──
  const hemi = new THREE.HemisphereLight(0xb0c8e8, 0x2a1a0a, 0.5);
  scene.add(hemi);

  const ambient = new THREE.AmbientLight(0x303848, 0.4);
  scene.add(ambient);

  const keyLight = new THREE.DirectionalLight(0xffeedd, 1.2);
  keyLight.position.set(60, 150, 80);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.set(2048, 2048);
  keyLight.shadow.camera.near = 1;
  keyLight.shadow.camera.far = 400;
  keyLight.shadow.camera.left = -80;
  keyLight.shadow.camera.right = 80;
  keyLight.shadow.camera.top = 200;
  keyLight.shadow.camera.bottom = -20;
  keyLight.shadow.bias = -0.001;
  scene.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0x6688cc, 0.5);
  fillLight.position.set(-50, 100, -40);
  scene.add(fillLight);

  const rimLight = new THREE.DirectionalLight(0xffa060, 0.35);
  rimLight.position.set(0, 50, -100);
  scene.add(rimLight);

  const topLight = new THREE.PointLight(0xeeeeff, 0.3, 300);
  topLight.position.set(0, 200, 0);
  scene.add(topLight);

  // ── Ground plane ──
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(600, 600),
    new THREE.MeshStandardMaterial({ color: 0x111118, roughness: 0.9, metalness: 0.1 }),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  let grid = new THREE.GridHelper(200, 40, 0x222244, 0x181828);
  grid.position.y = 0.05;
  scene.add(grid);

  // ── Post-processing ──
  const composer = new EffectComposer(renderer);
  composer.addPass(new RenderPass(scene, camera));

  const bloomPass = new UnrealBloomPass(
    new THREE.Vector2(W, H), 0.15, 0.4, 0.9,
  );
  composer.addPass(bloomPass);

  const smaaPass = new SMAAPass();
  composer.addPass(smaaPass);

  // ── Layer groups ──
  const layers: Record<LayerName, THREE.Group> = {} as any;
  for (const ln of ALL_LAYERS) {
    const g = new THREE.Group();
    g.name = ln;
    g.visible = DEFAULT_VISIBLE.has(ln);
    scene.add(g);
    layers[ln] = g;
  }

  // ── Index maps ──
  const boneMap = new Map<string, THREE.Mesh>();
  const boneDataById = new Map<string, BoneData>();
  const tendonById = new Map<string, TendonData>();
  const jointMap = new Map<string, THREE.Mesh>();
  const jointDataById = new Map<string, JointData>();

  for (const b of body.skeleton) boneDataById.set(b.id, b);
  for (const t of body.tendons) tendonById.set(t.id, t);
  for (const j of body.joints) jointDataById.set(j.id, j);

  // ════════════════════════════════════════════════════════════════════
  // SKELETON — 206 bones
  // ════════════════════════════════════════════════════════════════════

  for (const bone of body.skeleton) {
    const mat = boneMaterial(bone.region);
    let mesh: THREE.Mesh;

    if (bone.parentBoneId && bone.classification === "long") {
      const parent = boneDataById.get(bone.parentBoneId);
      if (parent) {
        // Long bones SPAN from parent position to this bone's position
        const from = toV3(parent.transform.position);
        const to = toV3(bone.transform.position);
        const distance = from.distanceTo(to);
        const midpoint = from.clone().add(to).multiplyScalar(0.5);

        // Use actual parent-child distance for geometry length
        const spanLen = Math.max(distance, 1);
        const geo = longBoneGeometry(spanLen, bone.width, bone.depth);
        mesh = new THREE.Mesh(geo, mat);

        // Position at midpoint between parent and this bone
        mesh.position.copy(midpoint);

        // Orient along parent→child direction
        const dir = to.clone().sub(from).normalize();
        const up = new THREE.Vector3(0, 1, 0);
        if (Math.abs(dir.dot(up)) < 0.999) {
          const q = new THREE.Quaternion().setFromUnitVectors(up, dir);
          mesh.quaternion.copy(q);
        }
      } else {
        // Parent not found, fall back to schema position
        const geo = boneGeometry(bone);
        mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(bone.transform.position.x, bone.transform.position.y, bone.transform.position.z);
      }
    } else {
      // Non-long bones: place at their own position
      const geo = boneGeometry(bone);
      mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(bone.transform.position.x, bone.transform.position.y, bone.transform.position.z);
    }

    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData = { type: "bone", id: bone.id, name: bone.name, region: bone.region };
    layers.skeleton.add(mesh);
    boneMap.set(bone.id, mesh);
  }

  // ════════════════════════════════════════════════════════════════════
  // JOINTS — 130
  // ════════════════════════════════════════════════════════════════════

  for (const joint of body.joints) {
    const dof = joint.degreesOfFreedom;
    const r = dof >= 3 ? 1.2 : dof === 2 ? 0.9 : 0.65;
    const geo = new THREE.SphereGeometry(r, 12, 8);
    const mesh = new THREE.Mesh(geo, jointMaterial());
    mesh.position.set(
      joint.transform.position.x,
      joint.transform.position.y,
      joint.transform.position.z,
    );
    mesh.userData = { type: "joint", id: joint.id, name: joint.name, dof };
    layers.joints.add(mesh);
    jointMap.set(joint.id, mesh);
  }

  // ════════════════════════════════════════════════════════════════════
  // MUSCLES — spindle-shaped bellies with variable radius
  // ════════════════════════════════════════════════════════════════════

  const tMat = tendonMaterial();
  for (const muscle of body.muscles) {
    const originTendon = tendonById.get(muscle.origin.tendonId);
    const insertionTendon = tendonById.get(muscle.insertion.tendonId);
    if (!originTendon || !insertionTendon) continue;

    const originBone = boneDataById.get(originTendon.attachedBoneId);
    const insertionBone = boneDataById.get(insertionTendon.attachedBoneId);
    if (!originBone || !insertionBone) continue;

    // World positions = bone position + tendon local offset
    const oPos = new THREE.Vector3(
      originBone.transform.position.x + originTendon.localPosition.x,
      originBone.transform.position.y + originTendon.localPosition.y,
      originBone.transform.position.z + originTendon.localPosition.z,
    );
    const iPos = new THREE.Vector3(
      insertionBone.transform.position.x + insertionTendon.localPosition.x,
      insertionBone.transform.position.y + insertionTendon.localPosition.y,
      insertionBone.transform.position.z + insertionTendon.localPosition.z,
    );

    // Muscle belly: curved spindle tube between origin and insertion
    // Multiple control points for anatomical curvature
    const mid = oPos.clone().add(iPos).multiplyScalar(0.5);
    const fiberDir = toV3(muscle.fiberDirection);
    const span = oPos.distanceTo(iPos);
    const bulge = span * 0.15;

    // 5 control points for smoother curvature
    const q1 = oPos.clone().lerp(mid, 0.25).add(fiberDir.clone().multiplyScalar(bulge * 0.6));
    const q2 = oPos.clone().lerp(mid, 0.5).add(fiberDir.clone().multiplyScalar(bulge));
    const q3 = mid.clone().lerp(iPos, 0.5).add(fiberDir.clone().multiplyScalar(bulge * 0.8));
    const q4 = mid.clone().lerp(iPos, 0.75).add(fiberDir.clone().multiplyScalar(bulge * 0.4));

    // Belly radius from volume: V ≈ π r² L → r = sqrt(V / (π L))
    const bellyR = Math.max(0.2, Math.min(3.0, Math.sqrt(muscle.volume / (Math.PI * Math.max(1, muscle.restingLength)))));
    const tR = bellyR * 0.2; // Tendon is much thinner than belly

    // Spindle-shaped tube: thin at tendons, thick at belly center
    const muscleGeo = variableRadiusTube(
      [oPos, q1, q2, q3, q4, iPos],
      24, // more segments for smooth spindle
      (t) => {
        // Smooth spindle profile: sin^0.7 creates a natural muscle belly shape
        const s = Math.pow(Math.sin(t * Math.PI), 0.7);
        return tR + (bellyR - tR) * s;
      },
      8,
    );

    const muscleMesh = new THREE.Mesh(muscleGeo, muscleMaterial(muscle.region));
    muscleMesh.castShadow = true;
    muscleMesh.userData = { type: "muscle", id: muscle.id, name: muscle.name, region: muscle.region };
    layers.muscles.add(muscleMesh);

    // Tendons: tapered tubes at origin and insertion ends
    const tendonR = Math.max(0.08, bellyR * 0.25);
    if (originTendon.length > 0.5) {
      const tEnd = oPos.clone().lerp(new THREE.Vector3(
        originBone.transform.position.x,
        originBone.transform.position.y,
        originBone.transform.position.z,
      ), 0.8);
      const tGeo = tubeFromPath([tEnd, oPos], tendonR, 4);
      const tMesh = new THREE.Mesh(tGeo, tMat);
      tMesh.userData = { type: "tendon", name: originTendon.name };
      layers.tendons.add(tMesh);
    }
    if (insertionTendon.length > 0.5) {
      const tEnd = iPos.clone().lerp(new THREE.Vector3(
        insertionBone.transform.position.x,
        insertionBone.transform.position.y,
        insertionBone.transform.position.z,
      ), 0.8);
      const tGeo = tubeFromPath([iPos, tEnd], tendonR, 4);
      const tMesh = new THREE.Mesh(tGeo, tMat);
      tMesh.userData = { type: "tendon", name: insertionTendon.name };
      layers.tendons.add(tMesh);
    }
  }

  // ════════════════════════════════════════════════════════════════════
  // VASCULAR SYSTEM — 94 vessels (arteries + veins)
  // ════════════════════════════════════════════════════════════════════

  for (const vessel of body.vascularSystem) {
    if (vessel.path.length < 2) continue;
    const pts = vessel.path.map(toV3);
    const r = Math.max(0.08, vessel.averageLumenRadius * 0.6);
    const geo = tubeFromPath(pts, r);
    const mat = vessel.vesselType === "artery" ? arteryMaterial() : veinMaterial();
    const mesh = new THREE.Mesh(geo, mat);
    mesh.userData = { type: "vessel", id: vessel.id, name: vessel.name, vesselType: vessel.vesselType };
    const layer = vessel.vesselType === "artery" ? layers.arteries : layers.veins;
    layer.add(mesh);
  }

  // ════════════════════════════════════════════════════════════════════
  // NERVES — 51
  // ════════════════════════════════════════════════════════════════════

  for (const nerve of body.nerves) {
    if (nerve.path.length < 2) continue;
    const pts = nerve.path.map(toV3);
    const r = nerve.type === "motor" ? 0.12 : nerve.type === "sensory" ? 0.1 : 0.15;
    const geo = tubeFromPath(pts, r);
    const mesh = new THREE.Mesh(geo, nerveMaterial());
    mesh.userData = { type: "nerve", id: nerve.id, name: nerve.name };
    layers.nerves.add(mesh);
  }

  // ════════════════════════════════════════════════════════════════════
  // ORGANS — 38 (with organ-specific geometries)
  // ════════════════════════════════════════════════════════════════════

  for (const organ of body.organs) {
    const geo = organGeometry(organ);
    const mesh = new THREE.Mesh(geo, organMaterial(organ.system));
    mesh.position.set(
      organ.transform.position.x,
      organ.transform.position.y,
      organ.transform.position.z,
    );
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData = { type: "organ", id: organ.id, name: organ.name, system: organ.system };
    layers.organs.add(mesh);
  }

  // ════════════════════════════════════════════════════════════════════
  // LIGAMENTS — 43
  // ════════════════════════════════════════════════════════════════════

  const ligMat = ligamentMaterial();
  for (const lig of body.ligaments) {
    const oBone = boneDataById.get(lig.originBoneId);
    const iBone = boneDataById.get(lig.insertionBoneId);
    if (!oBone || !iBone) continue;

    const oPos = new THREE.Vector3(
      oBone.transform.position.x + lig.originPosition.x,
      oBone.transform.position.y + lig.originPosition.y,
      oBone.transform.position.z + lig.originPosition.z,
    );
    const iPos = new THREE.Vector3(
      iBone.transform.position.x + lig.insertionPosition.x,
      iBone.transform.position.y + lig.insertionPosition.y,
      iBone.transform.position.z + lig.insertionPosition.z,
    );

    const r = Math.max(0.1, Math.min(0.6, lig.restingLength * 0.04));
    const geo = tubeFromPath([oPos, iPos], r, 4);
    const mesh = new THREE.Mesh(geo, ligMat);
    mesh.userData = { type: "ligament", id: lig.id, name: lig.name };
    layers.ligaments.add(mesh);
  }

  // ════════════════════════════════════════════════════════════════════
  // CARTILAGE — 36
  // ════════════════════════════════════════════════════════════════════

  for (const cart of body.cartilage) {
    const jointData = jointDataById.get(cart.jointId);
    if (!jointData) continue;

    const r = Math.sqrt(cart.surfaceArea / Math.PI);
    const geo = new THREE.CylinderGeometry(r, r, cart.thickness * 0.5, 12, 1);
    const mesh = new THREE.Mesh(geo, cartilageMaterial(cart.type));
    mesh.position.set(
      jointData.transform.position.x,
      jointData.transform.position.y,
      jointData.transform.position.z,
    );
    mesh.userData = { type: "cartilage", id: cart.id, name: cart.name };
    layers.cartilage.add(mesh);
  }

  // ── Dispose helper ──
  function dispose() {
    composer.dispose();
    renderer.dispose();
    controls.dispose();
    envMap.dispose();
    _materialCache.forEach((m) => m.dispose());
    _materialCache.clear();
    scene.traverse((obj: THREE.Object3D) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry.dispose();
      }
    });
    if (container.contains(renderer.domElement)) {
      container.removeChild(renderer.domElement);
    }
  }

  const themeRefs = { hemi, ambient, keyLight, fillLight, rimLight, ground, grid, bloom: bloomPass };

  return { scene, camera, renderer, composer, controls, layers, boneMap, jointMap, themeRefs, dispose };
}

// ═══════════════════════════════════════════════════════════════════════
// 7. HOVER / PICK — raycaster for tooltip
// ═══════════════════════════════════════════════════════════════════════

export interface PickResult {
  name: string;
  type: string;
  extra: Record<string, unknown>;
}

export function pick(
  handle: SceneHandle,
  ndc: THREE.Vector2,
  visibleLayers: Set<LayerName>,
): PickResult | null {
  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(ndc, handle.camera);

  const targets: THREE.Object3D[] = [];
  for (const ln of ALL_LAYERS) {
    if (visibleLayers.has(ln)) targets.push(handle.layers[ln]);
  }

  const hits = raycaster.intersectObjects(targets, true);
  if (hits.length === 0) return null;

  const hit = hits[0];
  if (!hit) return null;
  const ud = hit.object.userData as Record<string, unknown>;
  if (!ud?.name) return null;
  return { name: ud.name as string, type: ud.type as string, extra: ud };
}

// ═══════════════════════════════════════════════════════════════════════
// 8. REACT COMPONENT — <AnatomyViewer />
// ═══════════════════════════════════════════════════════════════════════

export interface AnatomyViewerProps {
  body: HumanBodyData;
}

const LAYER_ICONS: Record<LayerName, string> = {
  skeleton: "\u{1F9B4}",
  joints: "\u{1F535}",
  muscles: "\u{1F4AA}",
  tendons: "\u{1FAA2}",
  organs: "\u{1FAC0}",
  arteries: "\u{1F534}",
  veins: "\u{1F535}",
  nerves: "\u26A1",
  ligaments: "\u{1FA79}",
  cartilage: "\u{1FAE7}",
};

const LAYER_COLORS: Record<LayerName, string> = {
  skeleton: "#e8dbb8",
  joints: "#66aadd",
  muscles: "#bb3333",
  tendons: "#f0f0e8",
  organs: "#ddaa77",
  arteries: "#dd3322",
  veins: "#3344aa",
  nerves: "#eedd44",
  ligaments: "#d0d8c0",
  cartilage: "#c8dde8",
};

export default function AnatomyViewer({ body }: AnatomyViewerProps) {
  const mountRef = useRef<HTMLDivElement>(null);
  const handleRef = useRef<SceneHandle | null>(null);
  const [visibleLayers, setVisibleLayers] = useState<Set<LayerName>>(new Set(DEFAULT_VISIBLE));
  const [hovered, setHovered] = useState<PickResult | null>(null);
  const [stats, setStats] = useState({ fps: 0, tris: 0 });
  const [theme, setTheme] = useState<ThemeMode>("dark");
  const mouseRef = useRef<THREE.Vector2>(new THREE.Vector2(-10, -10));
  const ui = UI_THEMES[theme];

  const toggleTheme = useCallback(() => {
    setTheme((prev) => {
      const next: ThemeMode = prev === "dark" ? "light" : "dark";
      if (handleRef.current) applyTheme(handleRef.current, next);
      return next;
    });
  }, []);

  const toggleLayer = useCallback((layer: LayerName) => {
    setVisibleLayers((prev: Set<LayerName>) => {
      const next = new Set(prev);
      if (next.has(layer)) next.delete(layer);
      else next.add(layer);
      return next;
    });
  }, []);

  // Sync layer visibility to Three.js groups
  useEffect(() => {
    const h = handleRef.current;
    if (!h) return;
    for (const ln of ALL_LAYERS) {
      h.layers[ln].visible = visibleLayers.has(ln);
    }
  }, [visibleLayers]);

  // Scene lifecycle
  useEffect(() => {
    const ct = mountRef.current;
    if (!ct) return;

    const handle = buildScene(ct, body);
    handleRef.current = handle;

    let rafId: number;
    let lastTime = 0;
    let frameCount = 0;
    let fpsAccum = 0;

    function loop(ts: number) {
      rafId = requestAnimationFrame(loop);
      const dt = ts - lastTime;
      lastTime = ts;

      handle.controls.update();
      handle.composer.render();

      // FPS counter
      frameCount++;
      fpsAccum += dt;
      if (fpsAccum >= 1000) {
        const info = handle.renderer.info.render;
        setStats({ fps: Math.round(frameCount * 1000 / fpsAccum), tris: info.triangles });
        frameCount = 0;
        fpsAccum = 0;
      }

      // Hover pick (throttled to every 3rd frame)
      if (frameCount % 3 === 0) {
        const result = pick(handle, mouseRef.current, visibleLayers);
        setHovered(result);
      }
    }

    rafId = requestAnimationFrame(loop);

    const onResize = () => {
      const w = ct.clientWidth;
      const h = ct.clientHeight;
      handle.camera.aspect = w / h;
      handle.camera.updateProjectionMatrix();
      handle.renderer.setSize(w, h);
      handle.composer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);

    const onPointerMove = (e: PointerEvent) => {
      const rect = ct.getBoundingClientRect();
      mouseRef.current.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouseRef.current.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
    };
    ct.addEventListener("pointermove", onPointerMove);

    return () => {
      cancelAnimationFrame(rafId);
      window.removeEventListener("resize", onResize);
      ct.removeEventListener("pointermove", onPointerMove);
      handle.dispose();
      handleRef.current = null;
    };
  }, [body]);

  // Presets
  const presetAll = () => setVisibleLayers(new Set(ALL_LAYERS));
  const presetSkeleton = () => setVisibleLayers(new Set(["skeleton", "joints", "cartilage"]));
  const presetMuscular = () => setVisibleLayers(new Set(["muscles", "tendons"]));
  const presetVascular = () => setVisibleLayers(new Set(["arteries", "veins"]));
  const presetNervous = () => setVisibleLayers(new Set(["nerves", "skeleton"]));
  const presetOrgans = () => setVisibleLayers(new Set(["organs", "skeleton"]));

  const layerCounts: Record<LayerName, number> = {
    skeleton: body.skeleton.length,
    joints: body.joints.length,
    muscles: body.muscles.length,
    tendons: body.tendons.length,
    organs: body.organs.length,
    arteries: body.vascularSystem.filter((v) => v.vesselType === "artery").length,
    veins: body.vascularSystem.filter((v) => v.vesselType === "vein").length,
    nerves: body.nerves.length,
    ligaments: body.ligaments.length,
    cartilage: body.cartilage.length,
  };

  return (
    <div style={{ width: "100%", height: "100vh", position: "relative", fontFamily: "'Inter','SF Pro','Segoe UI',sans-serif", background: "#0c0c14", color: "#c8ccd4", overflow: "hidden" }}>
      {/* Three.js canvas mount */}
      <div ref={mountRef} style={{ position: "absolute", inset: 0, zIndex: 1 }} />

      {/* Title / identity */}
      <div style={{ position: "absolute", top: 12, left: 16, zIndex: 10 }}>
        <div style={{ fontSize: 14, fontWeight: 700, letterSpacing: 1, color: "#e8e8f0" }}>
          {body.name ?? "Human Body"} — Schema v{body.schemaVersion}
        </div>
        <div style={{ fontSize: 10, color: "#556688", marginTop: 2 }}>
          {body.proportions.biologicalSex ?? "unknown"} · {body.proportions.totalHeight}cm · {body.proportions.weight}kg
        </div>
      </div>

      {/* Stats */}
      <div style={{ position: "absolute", top: 12, right: 16, zIndex: 10, fontSize: 9, color: "#445566", textAlign: "right" }}>
        <div>{stats.fps} FPS · {(stats.tris / 1000).toFixed(1)}K tris</div>
        <div>{body.skeleton.length} bones · {body.muscles.length} muscles · {body.joints.length} joints</div>
      </div>

      {/* Layer control panel */}
      <div style={{
        position: "absolute", top: 70, left: 16, zIndex: 10,
        background: "rgba(12,12,20,.92)", border: "1px solid rgba(100,120,180,.15)",
        borderRadius: 10, padding: 12, backdropFilter: "blur(12px)", width: 200,
      }}>
        <div style={{ fontSize: 10, fontWeight: 700, color: "#8899bb", letterSpacing: 1, marginBottom: 8, textTransform: "uppercase" }}>
          Layers
        </div>
        {ALL_LAYERS.map((ln) => {
          const active = visibleLayers.has(ln);
          return (
            <button
              key={ln}
              onClick={() => toggleLayer(ln)}
              style={{
                display: "flex", alignItems: "center", gap: 8, width: "100%",
                background: active ? `${LAYER_COLORS[ln]}18` : "transparent",
                border: `1px solid ${active ? LAYER_COLORS[ln] + "55" : "rgba(80,90,120,.15)"}`,
                borderRadius: 6, padding: "4px 8px", marginBottom: 3, cursor: "pointer",
                color: active ? LAYER_COLORS[ln] : "#556677", fontSize: 10,
                fontFamily: "inherit", textAlign: "left", transition: "all .15s",
              }}
            >
              <span style={{ fontSize: 12 }}>{LAYER_ICONS[ln]}</span>
              <span style={{ flex: 1, textTransform: "capitalize" }}>{ln}</span>
              <span style={{ fontSize: 8, opacity: 0.7 }}>{layerCounts[ln]}</span>
            </button>
          );
        })}

        {/* Presets */}
        <div style={{ marginTop: 10, borderTop: "1px solid rgba(80,90,120,.15)", paddingTop: 8 }}>
          <div style={{ fontSize: 9, fontWeight: 700, color: "#667788", letterSpacing: 1, marginBottom: 6, textTransform: "uppercase" }}>
            Presets
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
            {([
              ["All", presetAll],
              ["Skeletal", presetSkeleton],
              ["Muscular", presetMuscular],
              ["Vascular", presetVascular],
              ["Nervous", presetNervous],
              ["Organs", presetOrgans],
            ] as [string, () => void][]).map(([label, fn]) => (
              <button
                key={label}
                onClick={fn}
                style={{
                  background: "rgba(60,80,120,.12)", border: "1px solid rgba(80,100,140,.2)",
                  color: "#8899bb", borderRadius: 4, padding: "2px 8px",
                  cursor: "pointer", fontSize: 9, fontFamily: "inherit",
                }}
              >
                {label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Hover tooltip */}
      {hovered && (
        <div style={{
          position: "absolute", bottom: 16, left: "50%", transform: "translateX(-50%)", zIndex: 10,
          background: "rgba(12,12,20,.94)", border: "1px solid rgba(100,120,180,.2)",
          borderRadius: 8, padding: "8px 16px", backdropFilter: "blur(10px)",
          textAlign: "center", pointerEvents: "none",
        }}>
          <div style={{ fontSize: 12, fontWeight: 600, color: "#e8e8f0" }}>{hovered.name}</div>
          <div style={{ fontSize: 9, color: "#667799", marginTop: 2, textTransform: "uppercase", letterSpacing: 1 }}>
            {hovered.type}
            {hovered.extra?.region ? ` · ${hovered.extra.region}` : ""}
            {hovered.extra?.system ? ` · ${hovered.extra.system}` : ""}
            {hovered.extra?.dof ? ` · ${hovered.extra.dof} DOF` : ""}
          </div>
        </div>
      )}

      {/* Theme toggle */}
      <button
        onClick={toggleTheme}
        style={{
          position: "absolute", top: 12, right: 200, zIndex: 10,
          background: ui.btnBg, border: `1px solid ${ui.btnBorder}`,
          color: ui.btnText, borderRadius: 6, padding: "4px 10px",
          cursor: "pointer", fontSize: 10, fontFamily: "inherit",
        }}
      >
        {theme === "dark" ? "Light" : "Dark"} Mode
      </button>

      {/* Controls hint */}
      <div style={{ position: "absolute", bottom: 16, right: 16, zIndex: 10, fontSize: 9, color: ui.textDim, textAlign: "right" }}>
        <div>LMB drag — orbit</div>
        <div>RMB drag — pan</div>
        <div>Scroll — zoom</div>
        <div>Hover — inspect</div>
      </div>
    </div>
  );
}
